scripts.check-careful:
import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'check-careful',
  description: 'Warn before destructive commands and workspace deletes (careful mode).',
  inputs: {
    toolName: { type: 'string', description: 'Matched MCP tool name.', required: true },
    args: { type: 'json', description: 'Tool arguments.', required: true },
    phase: { type: 'string', description: 'Hook phase.', required: true },
  },
  outputs: {
    decision: { type: 'string', description: 'allow | ask' },
    message: { type: 'string', description: 'Warning shown on ask.' },
  },
  requires: [],
});

// Build-artifact targets that are always safe to delete recursively —
// ported from check-careful.sh's exception list.
const SAFE_DELETE_TARGETS =
  /(?:^|\/)(node_modules|dist|build|coverage|\.next|\.cache|\.turbo|__pycache__)\/?$/;

// Destructive patterns checked against the stringified tool arguments —
// the ladder from check-careful.sh, minus host telemetry.
const PATTERNS: Array<[RegExp, string]> = [
  [/\brm\s+(-[a-z]*r|--recursive)/i, 'recursive delete (rm -r) permanently removes files'],
  [/\bdrop\s+(table|database)\b/i, 'SQL DROP permanently deletes database objects'],
  [/\btruncate\b/i, 'SQL TRUNCATE deletes all rows from a table'],
  [/\bgit\s+push\b[^\n]*(\s-f\b|--force)/i, 'git force-push rewrites remote history'],
  [/\bgit\s+reset\s+--hard/i, 'git reset --hard discards all uncommitted changes'],
  [/\bgit\s+(checkout|restore)\s+\./i, 'this discards all uncommitted changes in the working tree'],
  [/\bkubectl\s+delete\b/i, 'kubectl delete removes live resources'],
  [/\bdocker\s+(rm\s+-f|system\s+prune)/i, 'docker force-remove or prune deletes containers or images'],
];

// These tools execute code whose filesystem or external side effects cannot
// be inferred reliably from their call arguments. Careful mode therefore
// asks before the call instead of pretending a script-name scan is enough.
const OPAQUE_EXECUTION_TOOLS = new Set([
  'run_package_script',
  'run_npx',
  'run_nodejs_script',
  'derive_file',
  'run_playwright_script',
  'run_installed_script',
]);

async function main(): Promise<void> {
  const input = gezel.input as { toolName?: unknown; args?: Record<string, unknown> };
  const toolName = String(input.toolName ?? '');
  const args = input.args ?? {};

  if (toolName === 'delete_path') {
    const target = String((args as { path?: unknown }).path ?? '');
    if (target && SAFE_DELETE_TARGETS.test(target)) {
      gezel.output({ decision: 'allow', message: '' });
      return;
    }
    gezel.output({
      decision: 'ask',
      message: '[careful] Deleting "' + target + '" permanently removes it from the workspace.',
    });
    return;
  }

  if (OPAQUE_EXECUTION_TOOLS.has(toolName)) {
    gezel.output({
      decision: 'ask',
      message:
        '[careful] ' + toolName + ' executes code whose destructive side effects cannot be proven from the tool call. Review and approve it before it runs.',
    });
    return;
  }

  let text = '';
  try {
    text = JSON.stringify(args);
  } catch {
    text = String(args);
  }
  for (const [pattern, why] of PATTERNS) {
    if (pattern.test(text)) {
      gezel.output({ decision: 'ask', message: '[careful] Heads up: ' + why + '.' });
      return;
    }
  }
  gezel.output({ decision: 'allow', message: '' });
}

await main();

scripts.check-freeze:
import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'check-freeze',
  description: 'Block workspace writes outside the frozen directory (freeze scope).',
  inputs: {
    toolName: { type: 'string', description: 'Matched MCP tool name.', required: true },
    args: { type: 'json', description: 'Tool arguments.', required: true },
    phase: { type: 'string', description: 'Hook phase.', required: true },
  },
  outputs: {
    decision: { type: 'string', description: 'allow | deny' },
    message: { type: 'string', description: 'Reason shown on deny.' },
  },
  requires: ['workspace.read'],
});

const STATE_FILE = '.gezel/freeze.json';

function normalize(p: string): string {
  return p.replace(/\\/g, '/').replace(/\/{2,}/g, '/').replace(/^\.\//, '').replace(/\/$/, '');
}

async function main(): Promise<void> {
  const input = gezel.input as { toolName?: unknown; args?: Record<string, unknown> };
  const toolName = String(input.toolName ?? '');
  const args = input.args ?? {};

  let frozenDir = '';
  try {
    const raw = await gezel.fs.read(STATE_FILE);
    frozenDir = normalize(String(JSON.parse(raw).dir ?? ''));
  } catch {
    // Not configured yet (the setup step writes it) — allow everything.
    gezel.output({ decision: 'allow', message: '' });
    return;
  }
  if (!frozenDir) {
    gezel.output({ decision: 'allow', message: '' });
    return;
  }

  // Arbitrary code and project-type application can write paths that are not
  // declared in their tool arguments. Fail closed: direct file tools remain
  // available inside the boundary, while opaque executors must wait until
  // the freeze is lifted.
  const unboundedWriteTools = new Set([
    'npm_install',
    'run_package_script',
    'run_npx',
    'run_nodejs_script',
    'derive_file',
    'run_playwright_script',
    'run_installed_script',
    'apply_project_type',
  ]);
  if (unboundedWriteTools.has(toolName)) {
    gezel.output({
      decision: 'deny',
      message:
        '[freeze] ' + toolName + ' can write undeclared paths, so it is blocked while freeze scope is active. Use direct workspace tools inside "' + frozenDir + '/", or end the freeze before running code.',
    });
    return;
  }

  // Only write destinations count. Source paths may live elsewhere and are
  // safe to read (copy_artifact_to_workspace and extract_archive).
  const candidateKeys =
    toolName === 'rename'
      ? ['fromPath', 'toPath']
      : toolName === 'copy_artifact_to_workspace'
        ? ['dest']
        : toolName === 'extract_archive'
          ? ['outputPath']
          : ['path'];
  const candidates = candidateKeys
    .map((key) => (args as Record<string, unknown>)[key])
    .filter((value): value is string => typeof value === 'string' && value.length > 0)
    .map(normalize);
  if (candidates.length === 0) {
    gezel.output({
      decision: 'deny',
      message: '[freeze] This write call did not expose a destination path, so its boundary cannot be verified.',
    });
    return;
  }

  for (const candidate of candidates) {
    const inside = candidate === frozenDir || candidate.startsWith(frozenDir + '/');
    const isStateFile = candidate === normalize(STATE_FILE);
    if (candidate.includes('..')) {
      gezel.output({ decision: 'deny', message: '[freeze] Path escapes are blocked while freeze scope is active.' });
      return;
    }
    if (!inside && !isStateFile) {
      gezel.output({
        decision: 'deny',
        message:
          '[freeze] Writes are frozen to "' + frozenDir + '/" — "' + candidate + '" is outside it. Finish the scoped work first, or end the freeze-scope task to lift the boundary.',
      });
      return;
    }
  }
  gezel.output({ decision: 'allow', message: '' });
}

await main();

scripts.search-prior:
import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'search-prior',
  description:
    'Search project memory for prior investigations matching a symptom signature. Stamps {matches: number, hits: [{text, score}]}.',
  inputs: {
    symptom: {
      type: 'string',
      description: 'Short symptom description (1-3 sentences). Used as the search query.',
      required: true,
    },
  },
  outputs: {
    matches: { type: 'number', description: 'Number of memory hits returned.' },
    hits: {
      type: 'array',
      description: 'Top matches, each with text + score.',
      itemType: 'object',
    },
  },
  requires: ['memory.read'],
});

interface MemoryHit {
  text: string;
  score: number;
}

async function main(): Promise<void> {
  const input = gezel.input as { symptom: string };
  const query = `investigation: ${input.symptom}`;
  const results = (await gezel.memory.search(query)) as MemoryHit[];
  const filtered = (results ?? []).filter(
    (r): r is MemoryHit => Boolean(r) && typeof r.text === 'string' && typeof r.score === 'number',
  );
  gezel.log(`Memory search for "${query}" returned ${filtered.length} hit(s)`);
  gezel.output({ matches: filtered.length, hits: filtered.slice(0, 5) });
}

await main();

scripts.save-learning:
import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'save-learning',
  description:
    'Stamp a (symptom → root cause → fix) investigation triple into project memory so future `search-prior` queries find it.',
  inputs: {
    symptom: { type: 'string', description: 'Observable failure.', required: true },
    rootCause: { type: 'string', description: 'Root cause in one sentence.', required: true },
    fix: { type: 'string', description: 'Proposed fix.', required: true },
    files: {
      type: 'string',
      description: 'Comma-separated list of files touched (or expected to be touched).',
    },
  },
  outputs: {
    ok: { type: 'boolean', description: 'True on successful save.' },
  },
  requires: ['memory.write'],
});

async function main(): Promise<void> {
  const input = gezel.input as {
    symptom: string;
    rootCause: string;
    fix: string;
    files?: string;
  };
  const text = [
    'investigation:',
    `symptom: ${input.symptom}`,
    `root cause: ${input.rootCause}`,
    `fix: ${input.fix}`,
    ...(input.files ? [`files: ${input.files}`] : []),
  ].join('\n');
  await gezel.memory.save(text, {
    kind: 'investigation',
    ...(input.files ? { files: input.files } : {}),
  });
  gezel.log('Saved investigation to memory.');
  gezel.output({ ok: true });
}

await main();

scripts.qa-trace:
import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'qa-trace',
  description:
    'Navigate to a URL via run_playwright_script and capture an accessibility snapshot. Returns {loaded: boolean, snapshot: string, title: string}.',
  inputs: {
    url: { type: 'string', description: 'Target URL.', required: true },
    mode: {
      type: 'choice',
      description: 'What to do.',
      options: [{ value: 'smoke' }, { value: 'snapshot' }],
      default: 'smoke',
    },
  },
  outputs: {
    loaded: { type: 'boolean', description: 'True if the page loaded without a hard error.' },
    title: { type: 'string', description: 'Page title.', nullable: true },
    snapshot: { type: 'string', description: 'Truncated accessibility snapshot.' },
  },
  requires: ['network'],
});

async function main(): Promise<void> {
  const input = gezel.input as { url: string; mode?: string };
  const script = `
    import { chromium } from 'playwright';
    const browser = await chromium.launch();
    const ctx = await browser.newContext();
    const page = await ctx.newPage();
    let loaded = true;
    let title = '';
    try {
      const resp = await page.goto(${JSON.stringify(input.url)}, { waitUntil: 'domcontentloaded', timeout: 30_000 });
      if (resp && resp.status() >= 500) loaded = false;
      title = await page.title();
    } catch (err) {
      loaded = false;
    }
    const snap = await page.accessibility.snapshot({ interestingOnly: true }).catch(() => null);
    await browser.close();
    console.log(JSON.stringify({ loaded, title, snapshot: snap ? JSON.stringify(snap).slice(0, 16_000) : '' }));
  `;
  const raw = await gezel.mcp.call('run_playwright_script', { script });
  const text = typeof raw === 'string' ? raw : '';
  const jsonMatch = /\{[\s\S]*\}/.exec(text);
  if (!jsonMatch) {
    throw new Error(`run_playwright_script returned unparseable output: ${text.slice(0, 200)}`);
  }
  const parsed = JSON.parse(jsonMatch[0]!) as {
    loaded: boolean;
    title: string;
    snapshot: string;
  };
  gezel.log(`qa-trace ${input.url}: loaded=${parsed.loaded}, title="${parsed.title.slice(0, 80)}"`);
  gezel.output(parsed);
}

await main();

scripts.run-tests:
import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'run-tests',
  description:
    'Run the project test command via run_package_script. Stamps {passed: boolean, summary: string}.',
  inputs: {
    scriptName: {
      type: 'string',
      description: 'Override the npm script name. Defaults to "test".',
      default: 'test',
    },
  },
  outputs: {
    passed: { type: 'boolean', description: 'True iff the test command exited 0.' },
    summary: { type: 'string', description: 'Last ~2KB of stdout/stderr.' },
  },
  requires: ['workspace.read'],
});

interface PackageScriptResult {
  exitCode: number;
  stdout?: string;
  stderr?: string;
}

async function main(): Promise<void> {
  const input = gezel.input as { scriptName?: string };
  const scriptName = input.scriptName ?? 'test';
  const raw = await gezel.mcp.call('run_package_script', { script: scriptName });
  let parsed: PackageScriptResult | null = null;
  if (typeof raw === 'string') {
    try {
      parsed = JSON.parse(raw) as PackageScriptResult;
    } catch {
      // The MCP tool returns a text blob, not always JSON. We treat
      // "non-zero exit code" / "failed" / "FAIL " markers as failure.
    }
  }
  const text = typeof raw === 'string' ? raw : JSON.stringify(raw);
  const looksFailed =
    parsed?.exitCode !== undefined
      ? parsed.exitCode !== 0
      : /(?:^|\b)(?:fail|error|exit code [1-9]|✗)\b/i.test(text);
  const tail = text.length > 2048 ? text.slice(-2048) : text;
  gezel.log(`pnpm ${scriptName}: ${looksFailed ? 'failed' : 'passed'}`);
  gezel.output({ passed: !looksFailed, summary: tail });
}

await main();

scripts.open-pr:
import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'open-pr',
  description:
    'Open a pull request for the current branch via the GitHub MCP tools. Stamps {number, url} on success.',
  inputs: {
    title: { type: 'string', description: 'PR title. Falls back to a derived placeholder.' },
    body: { type: 'string', description: 'PR body. Markdown.' },
    head: {
      type: 'string',
      description: 'Source branch. Defaults to the current branch (caller must resolve).',
      required: true,
    },
    base: { type: 'string', description: 'Target branch.', default: 'main' },
    draft: { type: 'boolean', description: 'Open as draft.', default: false },
  },
  outputs: {
    number: { type: 'number', description: 'Created PR number.' },
    url: { type: 'string', description: 'PR URL.' },
  },
  requires: ['network'],
});

async function main(): Promise<void> {
  const input = gezel.input as {
    title?: string;
    body?: string;
    head: string;
    base?: string;
    draft?: boolean;
  };
  const title = input.title ?? `Ship: ${input.head}`;
  const args: Record<string, unknown> = {
    title,
    head: input.head,
    base: input.base ?? 'main',
  };
  if (input.body) args.body = input.body;
  if (input.draft !== undefined) args.draft = input.draft;
  const raw = await gezel.mcp.call('github_pr_create', args);
  const text = typeof raw === 'string' ? raw : '';
  const m = /Opened PR #(\d+) — (\S+)/.exec(text);
  if (!m) {
    throw new Error(`unexpected github_pr_create response: ${text.slice(0, 200)}`);
  }
  gezel.output({ number: Number(m[1]), url: m[2]! });
}

await main();

scripts.wait-checks:
import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'wait-checks',
  description:
    'Poll github_check_status for a ref until it settles. Returns {state: success|failure|pending|timeout, checks[]}.',
  inputs: {
    ref: { type: 'string', description: 'Branch name or commit sha.', required: true },
    timeoutMs: {
      type: 'number',
      description: 'How long to wait before giving up.',
      default: 600_000,
      integer: true,
    },
    pollIntervalMs: {
      type: 'number',
      description: 'How long between polls.',
      default: 15_000,
      integer: true,
    },
  },
  outputs: {
    state: { type: 'string', description: 'Final state: success / failure / timeout.' },
    checks: { type: 'array', description: 'Per-check breakdown.', itemType: 'object' },
  },
  requires: ['network'],
});

interface CheckBlock {
  name: string;
  status: string;
  conclusion: string | null;
  url?: string;
}

function parseChecks(text: string): { state: string; checks: CheckBlock[] } {
  const lines = text.split('\n');
  const stateLine = lines[0] ?? '';
  const stateMatch = /^State:\s*(\w+)/i.exec(stateLine);
  const state = stateMatch?.[1]?.toLowerCase() ?? 'unknown';
  const checks: CheckBlock[] = [];
  for (let i = 1; i < lines.length; i++) {
    const m = /^• (.+?) — (\S+?)(?:\s*\/\s*(\S+))?$/.exec(lines[i] ?? '');
    if (!m) continue;
    checks.push({
      name: m[1]!,
      status: m[2]!,
      conclusion: m[3] ?? null,
    });
  }
  return { state, checks };
}

async function main(): Promise<void> {
  const input = gezel.input as { ref: string; timeoutMs?: number; pollIntervalMs?: number };
  const deadline = Date.now() + (input.timeoutMs ?? 600_000);
  const poll = input.pollIntervalMs ?? 15_000;
  let lastState = 'unknown';
  let lastChecks: CheckBlock[] = [];
  while (Date.now() < deadline) {
    const raw = await gezel.mcp.call('github_check_status', { ref: input.ref });
    const text = typeof raw === 'string' ? raw : '';
    const parsed = parseChecks(text);
    lastState = parsed.state;
    lastChecks = parsed.checks;
    gezel.log(`checks for ${input.ref}: ${parsed.state} (${parsed.checks.length} check(s))`);
    if (parsed.state === 'success' || parsed.state === 'failure') {
      gezel.output({ state: parsed.state, checks: parsed.checks });
      return;
    }
    await new Promise((r) => setTimeout(r, poll));
  }
  gezel.output({ state: 'timeout', checks: lastChecks });
}

await main();
